input.command:
cd /tmp/<path> && python3 - <<'EOF'
import re, sys

lines = open('prog.pw9').read().splitlines()
prog = []
for ln in lines:
    code = ln.split(';')[0].strip()
    if code:
        prog.append(code)

print("INSTRUCTIONS:")
for i,p in enumerate(prog):
    print(i,p)
print()

regs = {'a':0,'b':0,'c':0,'d':0}

def val(x):
    if x in regs:
        return regs[x]
    return int(x)

def mod65536(v):
    return v % 65536

out = []
count = 0
ip = 0
steps = 0
while 0 <= ip < len(prog):
    steps += 1
    if steps > 10_000_000:
        print("TOO MANY"); break
    parts = prog[ip].split()
    op = parts[0]
    count += 1
    if op == 'set':
        regs[parts[1]] = val(parts[2]) % 65536
        ip += 1
    elif op == 'add':
        regs[parts[1]] = (regs[parts[1]] + val(parts[2])) % 65536
        ip += 1
    elif op == 'mul':
        regs[parts[1]] = (regs[parts[1]] * val(parts[2])) % 65536
        ip += 1
    elif op == 'mod':
        x = val(parts[2])
        if x > 0:
            regs[parts[1]] = regs[parts[1]] % x
        ip += 1
    elif op == 'dec':
        if regs[parts[1]] > 0:
            regs[parts[1]] -= 1
        ip += 1
    elif op == 'jnz':
        x = val(parts[1]); k = val(parts[2])
        if x != 0:
            ip += k
        else:
            ip += 1
    elif op == 'skp':
        x = val(parts[1]); y = val(parts[2])
        if x < y:
            ip += 2
        else:
            ip += 1
    elif op == 'out':
        out.append(val(parts[1]))
        ip += 1
    else:
        raise Exception(op)

print("num outputs:", len(out))
print("first 20:", out[:20])
print("last 20:", out[-20:])
print("sum:", sum(out))
print("count:", count)
print("regs:", regs)
EOF

