input.command:
cd /tmp/<path> && node - <<'EOF'
const fs=require('fs');
const prog=fs.readFileSync('prog.pw9','utf8').split('\n').map(l=>l.split(';')[0].trim()).filter(l=>l.length);
const R={a:0,b:0,c:0,d:0};
const val=x=> (x in R)?R[x]:parseInt(x,10);
const out=[];
let ip=0,count=0,iters=0;
while(ip>=0&&ip<prog.length){
  const p=prog[ip].split(/\s+/); const op=p[0]; count++;
  if(op==='set'){R[p[1]]=((val(p[2])%65536)+65536)%65536;ip++;}
  else if(op==='add'){R[p[1]]=((R[p[1]]+val(p[2]))%65536+65536)%65536;ip++;}
  else if(op==='mul'){R[p[1]]=((R[p[1]]*val(p[2]))%65536+65536)%65536;ip++;}
  else if(op==='mod'){const x=val(p[2]); if(x>0)R[p[1]]=R[p[1]]%x; ip++;}
  else if(op==='dec'){if(R[p[1]]>0)R[p[1]]--; ip++;}
  else if(op==='jnz'){val(p[1])!==0? ip+=val(p[2]) : ip++;}
  else if(op==='skp'){val(p[1])<val(p[2])? ip+=2 : ip++;}
  else if(op==='out'){out.push(val(p[1]));ip++;}
  if(ip===4) iters++;
}
console.log('outputs',out.length,'sum',out.reduce((a,b)=>a+b,0),'count',count,'iters',iters);
console.log('regs',R);
console.log('post-loop outs', out.slice(-3));
// sanity: count outputs during loop (out at idx6)
console.log('loop outs', out.length-3);
EOF

